"""Combine disjoint independently reviewed GPU followups, preserving baselines."""
from pathlib import Path
import collections,json

ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'data/deep-review/gpu-followup'
BASE=ROOT/'data/deep-review/gpu'

def write(path,data):path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')

def main():
    baseline=json.loads((BASE/'products.json').read_text())
    original_review={x['id']:x for x in json.loads((BASE/'review.json').read_text())}
    out={};owners={};rechecked={}
    for part in ['asus','gigabyte','local','professional']:
        products=json.loads((D/part/'products.json').read_text())
        for cid,record in products.items():
            assert cid not in out and cid not in baseline,(cid,'followup must not replace a confirmed baseline')
            assert original_review[cid]['state']=='exact_reference_unconfirmed',cid
            out[cid]=record;owners[cid]=part
        audit=D/part/'review.json'
        if audit.exists():
            for r in json.loads(audit.read_text()):rechecked[r['id']]={'workstream':part,'result':r}
        else:
            for cid in products:rechecked[cid]={'workstream':part,'result':{'id':cid,'state':'primary_identity_and_specs'}}
    reviewed=[]
    for cid,r in original_review.items():
        if r['state']!='exact_reference_unconfirmed':continue
        reviewed.append({'id':cid,'brand':r['brand'],'baselineState':r['state'],'followupState':'primary_specs_enriched' if cid in out else 'rechecked_unresolved' if cid in rechecked else 'not_rechecked_in_this_followup','details':rechecked.get(cid),'missingCompatibilityFields':[k for k in ['lengthMm','heightMm','thicknessMm','powerW','recommendedPsuW'] if k not in out.get(cid,{}).get('patch',{})]})
    # Preserve explicit unknowns when component patches are spread over the
    # imported archive. Missing dimensions/revision-dependent fields cannot
    # silently survive as if they had been verified by this followup.
    clear={cid:[k for k in ['lengthMm','heightMm','thicknessMm','powerW','recommendedPsuW','fanCount','fanSizeMm'] if k not in rec['patch'] or rec.get('fieldEvidence',{}).get(k,{}).get('conflicting')] for cid,rec in out.items()}
    clear={cid:keys for cid,keys in clear.items() if keys}
    write(D/'products.json',out);write(D/'review.json',reviewed);write(D/'cleared-fields.json',clear)
    summary={'baselineGpuCount':len(original_review),'baselinePrimaryProducts':len(baseline),'baselineUnresolved':sum(r['state']=='exact_reference_unconfirmed' for r in original_review.values()),'individuallyRechecked':len(rechecked),'newProducts':len(out),'combinedPrimaryProducts':len(baseline)+len(out),'remainingUnresolved':sum(r['state']=='exact_reference_unconfirmed' for r in original_review.values())-len(out),'byBrand':dict(collections.Counter(original_review[cid]['brand'] for cid in out)),'byIdentityKind':dict(collections.Counter(r['identityKind'] for r in out.values())),'typedFields':sum(len(r.get('fieldEvidence',{})) for r in out.values()),'specificationRows':sum(len(g['rows']) for r in out.values() for g in r['groups']),'fanCounts':sum('fanCount' in r['patch'] for r in out.values()),'fanDiameters':sum('fanSizeMm' in r['patch'] for r in out.values()),'currentOffers':sum(o['priceKind']=='current' for r in out.values() for o in r['offers']),'historicalOffers':sum(o['priceKind']=='last_known' for r in out.values() for o in r['offers'])}
    write(D/'summary.json',summary)
    module="// Generated by scripts/build-deep-gpu-followup.py from individually reviewed manufacturer evidence.\nimport type { VerifiedProduct } from './verifiedTypes'\n\nexport const deepGpuFollowupProducts: Record<string, VerifiedProduct> = "+json.dumps(out,ensure_ascii=False,indent=2)+"\n\n// Unknown sales SKUs and dimensions must not inherit values from imported archives.\nfor (const record of Object.values(deepGpuFollowupProducts)) {\n  if (record.identityKind === 'manufacturer-model') record.patch.manufacturerPartNumber = undefined\n}\nconst unconfirmedFields: Record<string, string[]> = "+json.dumps(clear)+"\nfor (const [id, fields] of Object.entries(unconfirmedFields)) {\n  for (const field of fields) (deepGpuFollowupProducts[id].patch as Record<string, unknown>)[field] = undefined\n}\n"
    (ROOT/'src/data/deepGpuFollowupCatalog.ts').write_text(module)
    print(json.dumps(summary,ensure_ascii=False))

if __name__=='__main__':main()
